INSERT INTO "public"."faqs" ("id", "question", "questionEn", "answer", "answerEn", "category", "sortOrder", "isActive", "createdAt") VALUES ('54950633-8fe1-449f-abe5-cd50dfff84e7', 'كيف يمكنني طلب خدمة؟', 'How can I order a service?', 'يمكنك تصفح الخدمات المتاحة، اختيار الخدمة المناسبة، ثم الضغط على "طلب الخدمة" واتباع الخطوات.', 'Browse available services, select the appropriate service, then click "Order Service" and follow the steps.', 'general', '1', 'true', '2026-07-30T22:01:33.281Z');
INSERT INTO "public"."faqs" ("id", "question", "questionEn", "answer", "answerEn", "category", "sortOrder", "isActive", "createdAt") VALUES ('8bfc14a6-23b8-4b34-88f6-5a1309a838fe', 'ما هي مدة تنفيذ الطلب؟', 'What is the order processing time?', 'تختلف مدة التنفيذ حسب نوع الخدمة. يتم توضيح المدة المتوقعة في صفحة تفاصيل كل خدمة.', 'Processing time varies by service type. The estimated duration is shown on each service detail page.', 'general', '2', 'true', '2026-07-30T22:01:33.704Z');
INSERT INTO "public"."faqs" ("id", "question", "questionEn", "answer", "answerEn", "category", "sortOrder", "isActive", "createdAt") VALUES ('9105e24b-f64c-4007-a536-e0f2655de337', 'كيف يمكنني تتبع طلبي؟', 'How can I track my order?', 'يمكنك تتبع طلبك من خلال لوحة التحكم الخاصة بك، حيث ستجد جميع طلباتك وحالتها محدثة.', 'You can track your order through your dashboard, where all your orders and their status are updated.', 'general', '3', 'true', '2026-07-30T22:01:34.125Z');
INSERT INTO "public"."faqs" ("id", "question", "questionEn", "answer", "answerEn", "category", "sortOrder", "isActive", "createdAt") VALUES ('f697b078-616f-40f5-b513-2d4da1f9a890', 'ما هي طرق الدفع المتاحة؟', 'What payment methods are available?', 'نوفر عدة طرق دفع تشمل فيزا، ماستركارد، MADA، Apple Pay، STC Pay، والتحويل البنكي.', 'We offer multiple payment methods including Visa, Mastercard, MADA, Apple Pay, STC Pay, and bank transfer.', 'payment', '4', 'true', '2026-07-30T22:01:34.545Z');
INSERT INTO "public"."faqs" ("id", "question", "questionEn", "answer", "answerEn", "category", "sortOrder", "isActive", "createdAt") VALUES ('702824b3-ec7e-4bac-9323-36b06db44244', 'هل يمكنني استرداد المبلغ؟', 'Can I get a refund?', 'نعم، يمكن استرداد المبلغ حسب سياسة الاسترداد لكل خدمة. يرجى التواصل مع فريق الدعم للمزيد من التفاصيل.', 'Yes, refunds are available according to each service''s refund policy. Please contact support for details.', 'payment', '5', 'true', '2026-07-30T22:01:34.966Z');
INSERT INTO "public"."faqs" ("id", "question", "questionEn", "answer", "answerEn", "category", "sortOrder", "isActive", "createdAt") VALUES ('de3be0a2-7d98-4ad3-b525-b3d0eade8ec3', 'كيف يمكنني التواصل مع الدعم الفني؟', 'How can I contact support?', 'يمكنك التواصل معنا عبر قسم "اتصل بنا" في الموقع، أو من خلال تذكرة دعم من لوحة التحكم.', 'You can contact us through the "Contact Us" section on the website, or via a support ticket from the dashboard.', 'support', '6', 'true', '2026-07-30T22:01:35.387Z');

-- Table: services (18 rows)
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('visa-business', 'تأشيرة عمل', 'Business Visa', 'استخراج تأشيرة العمل للمقيمين والزوار بهدف ممارسة الأعمال التجارية والنشاطات المختلفة.', 'Business visa issuance for commercial activities and business purposes.', 'نقدم خدمة استخراج تأشيرة العمل بشكل متكامل يشمل استشارة متخصصة وتجهيز جميع المستندات والتقديم المباشر للجهات المعنية.

فريقنا من الخبراء يضمن تقديماً احترافياً يزيد من فرص الموافقة. نتعامل مع جميع أنواع تأشيرة العمل بما فيها تأشيرات المناسبات التجارية والمؤتمرات.

نوفر متابعة شاملة من لحظة التقديم وحتى الاستلام مع إشعارات فورية بأي تحديثات. كما نقدم خدمات الترجمة والتصديق.

نسعى دائماً لتقديم تجربة مميزة تتجاوز توقعات عملائنا.', 'Comprehensive business visa with specialized consultation and document preparation.', 'visa-business', 'Briefcase', 'https://lr2eqyz4qxt9820o.public.blob.vercel-storage.com/services/1785390488336-v98pu6.png', 'VISAS', 'التأشيرات', 500.00, 'يبدأ من', 'Starting from', '5-7 أيام عمل', '5-7 business days', NULL, 'true', 'false', '{"استشارة مجانية أولية","تجهيز كامل للمستندات","تقديم السيرة الذاتية","متابعة حتى الاستلام","ترجمة المستندات","دعم متعدد اللغات"}', '{"Free consultation","Full document preparation","CV preparation","Follow-up to delivery","Document translation","Multi-language support"}', '{"جواز سفر ساري المفعول","خطاب رسمي من الشركة الداعية","عقد العمل أو العمل الحر","صور شخصية حديثة"}', '{"Valid passport","Invitation letter from company","Work contract","Recent photos"}', '[{"icon":"MessageSquare","title":"الاستشارة الأولية","description":"نحدد نوع التأشيرة المناسب ومتطلباتها"},{"icon":"FileText","title":"تجهيز المستندات","description":"نحضر جميع المستندات وفقاً للمواصفات الرسمية"},{"icon":"Send","title":"تقديم الطلب","description":"نقدم للسفارة مع جميع المستندات المطلوبة"},{"icon":"Bell","title":"المتابعة والتحديث","description":"نتابع المستمر ونبلّغك بأي مستندات إضافية"},{"icon":"Package","title":"استلام التأشيرة","description":"نسلم التأشيرة الجاهزة مع جميع التفاصيل"}]'::jsonb, '[{"icon":"MessageSquare","title":"Consultation","description":"Determine appropriate visa type and requirements"},{"icon":"FileText","title":"Prepare Documents","description":"Prepare all documents per official specs"},{"icon":"Send","title":"Submit Application","description":"Submit to embassy with all documents"},{"icon":"Bell","title":"Follow-up","description":"Track and notify of any additional needs"},{"icon":"Package","title":"Receive Visa","description":"Deliver completed visa with all details"}]'::jsonb, '[{"answer":"في معظم الحالات لا حاجة للحضور، يتولى فريقنا الإجراءات.","question":"هل أحتاج لحضور شخصي للسفارة؟"},{"answer":"تبدأ من 500 ر.س شاملة المستندات والتقديم والمتابعة.","question":"ما هي تكلفة تأشيرة العمل؟"},{"answer":"نعم، يمكننا مساعدتك في التحويل وفقاً للإجراءات الرسمية.","question":"هل يمكن تحويل تأشيرة السياحة لعمل؟"}]'::jsonb, '[{"answer":"In most cases, no. Our team handles all procedures.","question":"Do I need to attend personally?"},{"answer":"Starting from 500 SAR including documents, submission, and follow-up.","question":"What is the cost?"},{"answer":"Yes, we help with conversion through official procedures.","question":"Can I convert tourist to business visa?"}]'::jsonb, '{"جواز سفر ساري المفعول (12 شهر على الأقل)","خطاب دعوة من الشركة المستضيفة","سجل تجاري للشركة الداعية","صور شخصية بمواصفات الختم","خطاب من جهة العمل الحالية"}', '{"Valid passport (min 12 months)","Invitation letter","Company commercial registration","Stamp-spec photos","Current employer letter"}', 'from-[#2580eb] via-[#1d4ed8] to-[#3b82f6]', '1', '2026-07-30T02:20:34.581Z', '2026-07-30T02:48:10.550Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('visa-transit', 'تأشيرة عبور', 'Transit Visa', 'خدمة استخراج تأشيرة العبور للمسافرين عبر المملكة العربية السعودية في طريقهم إلى وجهة أخرى.', 'Transit visa for travelers passing through Saudi Arabia.', 'نوفر خدمة تأشيرة العبور بسرعة وكفاءة عالية للمسافرين عبر أراضي المملكة.whether في طريقكم إلى وجهة أخرى أو تخططون للتوقف القصير، نحن هنا لتسهيل إجراءاتكم.

فريقنا يتابع طلباتكم بشكل فوري ويهتم بتسريع الموافقة لضمان عدم تأخر رحلتكم. نتعامل مع جميع خطوط الطيران.

الخدمة متاحة على مدار الساعة لمواكبة مواعيد الرحلات المختلفة، مع دعم باللغات المتعددة.', 'Fast and efficient transit visa services available 24/7.', 'visa-transit', 'Plane', 'https://lr2eqyz4qxt9820o.public.blob.vercel-storage.com/services/1785390522138-8kwtyv.png', 'VISAS', 'التأشيرات', 150.00, 'يبدأ من', 'Starting from', '1-2 أيام عمل', '1-2 business days', NULL, 'true', 'false', '{"إنجاز سريع خلال 24 ساعة","بدون حضور شخصي","متابعة إلكترونية كاملة","دعم متعدد اللغات","متاح 24/7"}', '{"Fast 24h processing","No personal attendance","Full electronic follow-up","Multi-language support","Available 24/7"}', '{"جواز سفر ساري المفعول","تذكرة الطيران للوجهة","تأشيرة الدخول للبلد النهائي"}', '{"Valid passport","Flight ticket to destination","Entry visa for final destination"}', '[{"icon":"Upload","title":"تقديم الطلب","description":"أرسل طلبك مع المستندات عبر المنصة"},{"icon":"Zap","title":"معالجة سريعة","description":"نتعامل مع طلبك فوراً لضمان عدم تأخر رحلتك"},{"icon":"Mail","title":"استلام التأشيرة","description":"تصدر التأشيرة إلكترونياً وتُرسل لبريدك"}]'::jsonb, '[{"icon":"Upload","title":"Submit Request","description":"Send request with documents via platform"},{"icon":"Zap","title":"Fast Processing","description":"Immediate handling to avoid travel delays"},{"icon":"Mail","title":"Receive Visa","description":"Visa issued electronically and emailed to you"}]'::jsonb, '[{"answer":"قد لا تحتاجها إذا بقيت في المنطقة المحظورة بالمطار.","question":"هل أحتاج تأشيرة عبور إذا كان انتظاري أقل من 12 ساعة؟"},{"answer":"عادة من 24 إلى 48 ساعة عمل فقط.","question":"كم تستغرق إصدار تأشيرة العبور؟"}]'::jsonb, '[{"answer":"Not if staying in the airport restricted area.","question":"Do I need a transit visa for under 12 hours?"},{"answer":"Usually 24-48 business hours.","question":"How long does a transit visa take?"}]'::jsonb, '{"جواز سفر ساري المفعول","تذكرة طيران مؤكد للوجهة التالية","تأشيرة الدخول للبلد النهائي"}', '{"Valid passport","Confirmed flight ticket","Entry visa for final country"}', 'from-[#2580eb] via-[#60a5fa] to-[#93c5fd]', '2', '2026-07-30T02:20:35.427Z', '2026-07-30T02:48:44.320Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('visa-residency', 'إقامة ومقيمين', 'Residency Permit', 'خدمة استخراج وتجديد الإقامة للمقيمين في المملكة العربية السعودية عبر أبشر ووزارة الداخلية.', 'Residency permit issuance and renewal through Absher and Ministry of Interior.', 'نقدم خدمة متكاملة لاستخراج وتجديد إقامة المقيمين من خلال المنصات الحكومية الرسمية. نتابع جميع الإجراءات عبر نظام أبشر ووزارة الداخلية بكفاءة وسرعة.

فريقنا يضمن إنجاز إجراءات الإقامة في أسرع وقت، سواء الاستخراج الأولي أو التجديد أو التعديل. نتعامل مع جميع أنواع الإقامات.

نقدم استشارة مجانية حول نوع الإقامة المناسب ومتطلباتها، ونتابع حتى الانتهاء الكامل.

نلتزم بالمواعيد النهائية ونوفر تحديثات دورية حول حالة طلبكم.', 'Comprehensive residency services through official government platforms.', 'visa-residency', 'Home', 'https://lr2eqyz4qxt9820o.public.blob.vercel-storage.com/services/1785390540258-svi5qv.png', 'VISAS', 'التأشيرات', 350.00, 'يبدأ من', 'Starting from', '2-4 أيام عمل', '2-4 business days', NULL, 'true', 'true', '{"تجديد سريع وآمن","متابعة حالة المعاملة","تنسيق مع جهة العمل","إشعار عند الانتهاء","استشارة مجانية","جميع أنواع الإقامات"}', '{"Fast and safe renewal","Status tracking","Employer coordination","Completion notification","Free consultation","All residency types"}', '{"جواز سفر ساري المفعول","صورة الهوية الوطنية","عقد العمل الحالي","صور حديثة"}', '{"Valid passport","National ID copy","Current work contract","Recent photos"}', '[{"icon":"MessageSquare","title":"استشارة أولية","description":"نحدد نوع الإقامة ومتطلباتها"},{"icon":"FileText","title":"تجهيز المستندات","description":"نجمع ونرتب المستندات المطلوبة"},{"icon":"Monitor","title":"تقديم المعاملة","description":"نقدم عبر منصة أبشر أو الوزارة المختصة"},{"icon":"CheckCircle","title":"المتابعة والإنجاز","description":"نتابع حتى الانتهاء ونبلّغك بالنتيجة"}]'::jsonb, '[{"icon":"MessageSquare","title":"Consultation","description":"Determine residency type and requirements"},{"icon":"FileText","title":"Prepare Documents","description":"Collect and arrange required documents"},{"icon":"Monitor","title":"Submit Transaction","description":"Submit via Absher or relevant ministry"},{"icon":"CheckCircle","title":"Follow-up","description":"Track until completion and notify you"}]'::jsonb, '[{"answer":"نعم، عبر منصة أبشر في حال استيفاء الشروط. فريقنا يتابع بالكامل.","question":"هل يمكن تجديد الإقامة عبر الإنترنت؟"},{"answer":"تبدأ من 350 ر.س شاملة جميع الإجراءات.","question":"ما هي تكلفة التجديد؟"},{"answer":"عادة من 2 إلى 4 أيام عمل.","question":"كم تستغرق عملية التجديد؟"}]'::jsonb, '[{"answer":"Yes, through Absher if conditions are met.","question":"Can I renew online?"},{"answer":"Starting from 350 SAR.","question":"What is the renewal cost?"},{"answer":"Usually 2-4 business days.","question":"How long does renewal take?"}]'::jsonb, '{"جواز سفر ساري المفعول","هوية وطنية أو إقامة حالية","عقد العمل أو خطاب جهة العمل","صور شخصية حديثة","آخر كشف رواتب"}', '{"Valid passport","Current ID or residency","Work contract or employer letter","Recent photos","Latest salary statement"}', 'from-[#2580eb] via-[#818cf8] to-[#a78bfa]', '3', '2026-07-30T02:20:36.074Z', '2026-07-30T02:49:02.606Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('contract-rental', 'عقود الإيجار', 'Rental Contracts', 'إعداد عقود الإيجار المعتمدة من الوزارة مع تسجيلها في منصة عقار.', 'Rental contract preparation approved by the Ministry, registered on Aqar platform.', 'نقدم خدمة إعداد عقود الإيجار المعتمدة رسمياً من وزارة الشؤون البلدية والقروية والسكنى وتسجيلها في منصة عقار. نضمن عقداً قانونياً صحيحاً يحمي حقوقك كمؤجر أو مستأجر.

فريقنا يإعداد العقد وفقاً للصيغ المعتمدة مع مراعاة جميع الظروف الخاصة بكل عقد.

الخدمة تشمل التسجيل في منصة عقار إلكترونياً مما يضمن صحته القانونية وسهولة الوصول إليه.

نسعى دائماً لتجربة سلسة تحمي حقوق جميع الأطراف.', 'Official rental contracts with Aqar platform registration.', 'contract-rental', 'FileSignature', 'https://lr2eqyz4qxt9820o.public.blob.vercel-storage.com/services/1785390578981-6eytss.png', 'CONTRACTS', 'العقود', 250.00, 'يبدأ من', 'Starting from', '1 يوم عمل', '1 business day', NULL, 'true', 'true', '{"صيغة معتمدة رسمياً","تسجيل في منصة عقار","نسخ متعددة للطرفين","استشارة قانونية شاملة","إنجاز خلال يوم"}', '{"Official approved format","Aqar registration","Multiple copies","Legal consultation","Completed in 1 day"}', '{"هوية المؤجر","هوية المستأجر","صك ملكية العقار","بيانات العقار الكاملة"}', '{"Owner ID","Tenant ID","Property deed","Complete property details"}', '[{"icon":"ClipboardList","title":"جمع البيانات","description":"نجمع بيانات العقار والأطراف المعنية"},{"icon":"FileSignature","title":"إعداد العقد","description":"نعد العقد بالصيغة المعتمدة من الوزارة"},{"icon":"Globe","title":"تسجيل في عقار","description":"نسجل العقد في منصة عقار إلكترونياً"},{"icon":"Package","title":"تسليم النسخ","description":"نسلم النسخ المطبوعة للطرفين"}]'::jsonb, '[{"icon":"ClipboardList","title":"Collect Data","description":"Gather property and party information"},{"icon":"FileSignature","title":"Prepare Contract","description":"Prepare in Ministry-approved format"},{"icon":"Globe","title":"Register on Aqar","description":"Register electronically on Aqar platform"},{"icon":"Package","title":"Deliver Copies","description":"Deliver printed copies to both parties"}]'::jsonb, '[{"answer":"نعم، بتفويض رسمي من المالك مع المستندات المطلوبة.","question":"هل يمكن تسجيل العقد بدون حضور المالك؟"},{"answer":"نعم، معتمد من الوزارة ومسجل في منصة عقار.","question":"هل العقد معتمد قانونياً؟"}]'::jsonb, '[{"answer":"Yes, with official power of attorney.","question":"Can I register without the owner present?"},{"answer":"Yes, Ministry-approved and Aqar-registered.","question":"Is the contract legally valid?"}]'::jsonb, '{"هوية المالك الأصلية","صك ملكية العقار أو استمارة 7001","هوية المستأجر","بيانات العقار (المساحة والدور)","اتفاقيات سابقة بين الأطراف"}', '{"Owner original ID","Property deed or form 7001","Tenant ID","Property details","Previous agreements"}', 'from-[#14b8a6] via-[#06b6d4] to-[#22d3ee]', '5', '2026-07-30T02:20:37.371Z', '2026-07-30T02:49:43.719Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('vehicle-transfer', 'نقل ملكية المركبات', 'Vehicle Ownership Transfer', 'إنجاز إجراءات نقل ملكية المركبات بين الأفراد بسهولة وسرعة.', 'Complete vehicle ownership transfer between individuals.', 'نقدم خدمة نقل ملكية المركبات بشكل متكامل يشمل جميع الإجراءات من الفحص الفني إلى تجديد التأمين واستخراج اللوحة الجديدة.

فريقنا يتولى جميع الإجراءات نيابة عنك من متابعة الفحص الفني إلى التسجيل في المنصات الحكومية.

الخدمة تشمل فحص المركبة وتجديد التأمين واستخراج اللوحة الجديدة وتوصيل الوثائق.

نسعى لتقديم خدمة مريحة وموثوقة توفر وقتك وجهدك.', 'Complete door-to-door vehicle ownership transfer service.', 'vehicle-transfer', 'Car', 'https://lr2eqyz4qxt9820o.public.blob.vercel-storage.com/services/1785390602591-x3haao.png', 'VEHICLES', 'المركبات', 400.00, 'يبدأ من', 'Starting from', '1-2 أيام عمل', '1-2 business days', NULL, 'true', 'true', '{"إنجاز جميع الإجراءات","تجديد التأمين الكلي","استخراج لوحة جديدة","توصيل الوثائق","فحص فني معتمد","خدمة من الباب للباب"}', '{"Complete procedures","Insurance renewal","New plate issuance","Document delivery","Certified inspection","Door-to-door service"}', '{"هوية البائع والمشتري","شهادة فحص المركبة","عقد البيع الأصلي","سجل المركبة"}', '{"Seller and buyer IDs","Inspection certificate","Sale contract","Vehicle registration"}', '[{"icon":"Car","title":"فحص المركبة","description":"نرتب للفحص في المركز المعتمد الأقرب"},{"icon":"FileText","title":"إعداد المستندات","description":"نجهز المستندات المطلوبة لعملية النقل"},{"icon":"Monitor","title":"التسجيل الرسمي","description":"نسجل نقل الملكية في المنصة الحكومية"},{"icon":"CreditCard","title":"اللوحة والتأمين","description":"نستخرج اللوحة الجديدة ونجدّد التأمين"},{"icon":"Truck","title":"توصيل الوثائق","description":"نوصّل الوثائق الجديدة للعنوان المحدد"}]'::jsonb, '[{"icon":"Car","title":"Inspection","description":"Arrange at nearest certified center"},{"icon":"FileText","title":"Prepare Documents","description":"Prepare all transfer documents"},{"icon":"Monitor","title":"Registration","description":"Register on government platform"},{"icon":"CreditCard","title":"Plate & Insurance","description":"New plate and insurance renewal"},{"icon":"Truck","title":"Deliver Documents","description":"Deliver to specified address"}]'::jsonb, '[{"answer":"لا، يتولى فريقنا الإجراءات. قد تحتاج حضور الفحص فقط.","question":"هل أحتاج لحضور شخصي؟"},{"answer":"تبدأ من 400 ر.س شاملة الفحص والتسجيل واللوحة والتأمين.","question":"ما هي التكلفة الشاملة؟"}]'::jsonb, '[{"answer":"No, except optionally for inspection.","question":"Do I need to be present?"},{"answer":"Starting from 400 SAR including inspection, registration, plate, and insurance.","question":"What is the total cost?"}]'::jsonb, '{"هوية البائع الأصلية","هوية المشتري الأصلية","رخصة المركبة","شهادة الفحص الفني","عقد البيع موقّع من الطرفين"}', '{"Seller original ID","Buyer original ID","Vehicle registration","Inspection certificate","Signed sale contract"}', 'from-[#7c3aed] via-[#8b5cf6] to-[#a78bfa]', '6', '2026-07-30T02:20:38.009Z', '2026-07-30T02:50:05.833Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('vehicle-deregister', 'إسقاط المركبات', 'Vehicle Deregistration', 'إنجاز إجراءات إسقاط المركبات من السجلات الرسمية وتجهيز المستندات اللازمة.', 'Vehicle deregistration from official records.', 'نقدم خدمة إسقاط المركبات من السجلات الرسمية بشكل رسمي وسريع. سواء كنت تريد إسقاط مركبة قديمة أو تالفة أو غير مستخدمة.

فريقنا يتابع جميع الإجراءات مع الجهات الحكومية المختصة ونضمن إتمام العملية بشكل قانوني وسليم.

الخدمة تشمل إعداد المستندات والتقديم للجهات وإشعارك بالاكتمال مع تقرير مفصل.

نسعى لتقديم خدمة سريعة تخلّصك من أعباء الإجراءات الحكومية.', 'Official vehicle deregistration handled efficiently.', 'vehicle-deregister', 'Car', 'https://lr2eqyz4qxt9820o.public.blob.vercel-storage.com/services/1785390656261-uditjf.png', 'VEHICLES', 'المركبات', 200.00, 'يبدأ من', 'Starting from', '1-3 أيام عمل', '1-3 business days', NULL, 'true', 'false', '{"إنجاز سريع","إشعار فوري بالاكتمال","تجهيز جميع المستندات","متابعة حتى الإغلاق","تقرير مفصل"}', '{"Fast processing","Instant completion notice","All documents prepared","Follow-up to closure","Detailed report"}', '{"هوية المالك الحالي","رخصة المركبة","لوحة المركبة","سبب الإسقاط"}', '{"Current owner ID","Vehicle registration","Vehicle plate","Reason for deregistration"}', '[{"icon":"FileText","title":"تقديم الطلب","description":"نجمع المستندات ونعد طلب الإسقاط"},{"icon":"Send","title":"تقديم للجهة","description":"نقدم للجهة الحكومية المختصة"},{"icon":"CheckCircle","title":"متابعة الإنجاز","description":"نتابع حتى الإشعار بالاكتمال"}]'::jsonb, '[{"icon":"FileText","title":"Submit Request","description":"Prepare documents and deregistration request"},{"icon":"Send","title":"Submit to Authority","description":"Submit to relevant government authority"},{"icon":"CheckCircle","title":"Track Completion","description":"Follow up until completion notice"}]'::jsonb, '[{"answer":"عادة من 1 إلى 3 أيام عمل.","question":"كم يستغرق إسقاط المركبة؟"},{"answer":"هوية المالك ورخصة المركبة ولوحتها وسبب الإسقاط.","question":"ما هي المستندات المطلوبة؟"}]'::jsonb, '[{"answer":"Usually 1-3 business days.","question":"How long does deregistration take?"},{"answer":"Owner ID, registration, plate, and reason for deregistration.","question":"What documents are needed?"}]'::jsonb, '{"هوية المالك الأصلية","رخصة المركبة الأصلية","لوحة المركبة","خطاب أو سبب الإسقاط"}', '{"Owner original ID","Vehicle registration","Vehicle plate","Deregistration reason letter"}', 'from-[#7c3aed] via-[#c084fc] to-[#e879f9]', '7', '2026-07-30T02:20:38.651Z', '2026-07-30T02:50:59.059Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('travel-booking', 'إدارة وإنجاز حجوزات السفر', 'Travel Booking Management', 'حجز وتأكيد تذاكر السفر والرحلات الداخلية والخارجية بأفضل الأسعار.', 'Book and confirm travel tickets at the best prices.', 'نقدم خدمة حجز وتأكيد تذاكر السفر والرحلات الداخلية والخارجية بأفضل الأسعار المتاحة في السوق. نبحث عن أفضل العروض وننسّق جميع التفاصيل لرحلتك.

فريقنا المختص يتعامل مع شركات الطيران والموزعين لضمان حصولك على أفضل سعر وأفضل شروط.

الخدمة تشمل حجز التذاكر وترتيب الفنادق والنقل من وإلى المطار مع تأمين السفر الشامل.

