e multi-flight bookings for best prices.","question":"Can I book multiple flights?"},{"answer":"Yes, comprehensive travel insurance can be added.","question":"Does the service include insurance?"},{"answer":"Our team searches airlines and distributors for the best deal.","question":"How do I get the best price?"}]'::jsonb, '{"جواز سفر ساري المفعول","التواريخ المطلوبة","عدد المسافرين","الميزانية المتوقعة","تفضيلات السفر"}', '{"Valid passport","Required dates","Number of travelers","Expected budget","Travel preferences"}', 'from-[#f59e0b] via-[#f97316] to-[#ef4444]', '9', '2026-07-30T02:20:39.929Z', '2026-07-30T02:51:39.055Z');
INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('hotel-booking', 'حجز الفنادق', 'Hotel Booking', 'حجز أفضل الفنادق والإقامات بأسعار تنافسية مع ترتيب جميع التفاصيل.', 'Book the best hotels at competitive prices with all logistics arranged.', 'نقدم خدمة حجز أفضل الفنادق والإقامات بأسعار تنافسية في جميع المدن والمواقع السياحية. نتعامل مع فنادق عالمية ومحلية لضمان خيارات متنوعة تناسب ميزانيتك.

فريقنا ينسّق جميع تفاصيل الإقامة من الحجز إلى تسجيل الدخول والخروج مع ترتيب أي خدمات إضافية تحتاجها.

الخدمة تشمل مقارنة الأسعار بين الفنادق المختلفة واختيار الأنسب من حيث الموقع والجودة والسعر.

