INSERT INTO "public"."services" ("id", "name", "nameEn", "description", "descriptionEn", "fullDescription", "fullDescriptionEn", "slug", "icon", "image", "category", "categoryAr", "price", "priceNote", "priceNoteEn", "duration", "durationEn", "durationUnit", "isActive", "isPopular", "features", "featuresEn", "requirements", "requirementsEn", "steps", "stepsEn", "faq", "faqEn", "requiredDocuments", "requiredDocumentsEn", "gradient", "sortOrder", "createdAt", "updatedAt") VALUES ('business-services', 'خدمات قطاع الأعمال', 'Business Services', 'خدمات متكاملة لتأسيس وإدارة الشركات والأعمال من سجل تجاري إلى التراخيص اللازمة.', 'Comprehensive company establishment and management services.', 'نقدم خدمات متكاملة لتأسيس الشركات والأعمال تشمل استخراج السجل التجاري والحصول على التراخيص اللازمة وإعداد النظام الداخلي.

