INSERT INTO "public"."site_content" ("id", "section", "data", "updatedAt") VALUES ('1661a48a-8eb1-4df7-95d2-5126cda74f71', 'homepage', '{"hero":{"titleAr":"حلول متكاملة لتلبية احتياجاتك","titleEn":"Integrated Solutions for Your Needs","subtitleAr":"نقدم أفضل الخدمات في التأشيرات، السفر، الأعمال، والاستشارات","subtitleEn":"We offer the best services in visas, travel, business, and consultations","descriptionAr":"حلول سريعة وموثوقة لاحتياجاتك الإلكترونية","descriptionEn":"Fast and reliable solutions for your electronic needs","button1Ar":"تصفح خدماتنا","button1En":"Browse Services","button2Ar":"تتبع طلبك","button2En":"Track Order","image":""},"stats":[{"number":"17+","labelAr":"خدمة متكاملة","labelEn":"Services"},{"number":"500+","labelAr":"عميل سعيد","labelEn":"Happy Clients"},{"number":"1000+","labelAr":"طلب منجز","labelEn":"Orders Completed"}],"whyUs":[{"icon":"Zap","descAr":"ننجز طلباتك في أسرع وقت ممكن","descEn":"We complete your requests in the fastest time","titleAr":"السرعة","titleEn":"Speed"},{"icon":"Shield","descAr":"نضمن حماية بياناتك","descEn":"We ensure the protection of your data","titleAr":"الأمان","titleEn":"Security"},{"icon":"BadgePercent","descAr":"أسعار تنافسية وشفافة","descEn":"Competitive and transparent prices","titleAr":"الأسعار","titleEn":"Prices"},{"icon":"Headphones","descAr":"فريق دعم متاح على مدار الساعة","descEn":"Support team available 24/7","titleAr":"الدعم","titleEn":"Support"},{"icon":"Award","descAr":"نلتزم بأعلى معايير الجودة","descEn":"Highest quality standards","titleAr":"الجودة","titleEn":"Quality"},{"icon":"Heart","descAr":"أكثر من 10,000 عميل يثقون بنا","descEn":"Over 10,000 clients trust us","titleAr":"الثقة","titleEn":"Trust"}],"steps":[{"num":"01","descAr":"تصفح خدماتنا واختر ما يناسبك","descEn":"Browse and choose what fits your needs","titleAr":"اختر الخدمة","titleEn":"Choose Service"},{"num":"02","descAr":"املأ البيانات وأرسل طلبك بسهولة","descEn":"Fill in details and submit easily","titleAr":"أرسل طلبك","titleEn":"Submit